const CATS={식비:{icon:'🍚',color:'#f5a34a'},카페:{icon:'☕',color:'#bd8d6c'},생활:{icon:'🧻',color:'#a8d9c9'},교통:{icon:'🚌',color:'#86b9d5'},쇼핑:{icon:'🛍️',color:'#f5b9b6'},건강:{icon:'💊',color:'#a9c989'},주거:{icon:'🏠',color:'#d2a7df'},기타:{icon:'✨',color:'#b5aca2'},월급:{icon:'💰',color:'#79b999'},용돈:{icon:'🎁',color:'#e5aa61'}};
const EXPENSE_CATS=['식비','카페','생활','교통','쇼핑','건강','주거','기타'];
const INCOME_CATS=['월급','용돈','기타'];
const STORE='fox-yubu-ledger-v1';
const won=n=>new Intl.NumberFormat('ko-KR').format(Math.round(n||0))+'원';
const iso=d=>d.toLocaleDateString('sv-SE');
const today=new Date();
let state=load();let viewDate=new Date(today.getFullYear(),today.getMonth(),1);let filter='all';let entryType='expense';let entryOwner='나';let entryCat='식비';let editingId=null;

function seed(){const y=today.getFullYear(),m=today.getMonth(),d=n=>iso(new Date(y,m,Math.max(1,today.getDate()-n)));return{budget:2800000,catBudgets:{식비:500000,카페:120000,생활:180000,교통:150000,쇼핑:250000,건강:100000,주거:900000,기타:150000},transactions:[{id:1,type:'income',amount:3200000,date:d(8),category:'월급',memo:'이번 달 월급',owner:'나'},{id:2,type:'income',amount:2500000,date:d(7),category:'월급',memo:'월급',owner:'아내'},{id:3,type:'expense',amount:84000,date:d(1),category:'식비',memo:'주말 장보기',owner:'아내'},{id:4,type:'expense',amount:13800,date:d(2),category:'카페',memo:'동네 카페',owner:'나'},{id:5,type:'expense',amount:54000,date:d(3),category:'교통',memo:'주유',owner:'나'},{id:6,type:'expense',amount:120000,date:d(5),category:'생활',memo:'생활용품',owner:'아내'},{id:7,type:'expense',amount:890000,date:d(9),category:'주거',memo:'관리비와 월세',owner:'나'}]}}
function load(){try{return JSON.parse(localStorage.getItem(STORE))||seed()}catch{return seed()}}function save(){localStorage.setItem(STORE,JSON.stringify(state));return window.firebaseLedger.save(state).catch(()=>toast('Firebase 저장에 실패했어요'))}
function monthTx(){return state.transactions.filter(t=>{const d=new Date(t.date+'T00:00:00');return d.getFullYear()===viewDate.getFullYear()&&d.getMonth()===viewDate.getMonth()})}
function totals(){const tx=monthTx();return{income:tx.filter(t=>t.type==='income').reduce((a,t)=>a+t.amount,0),expense:tx.filter(t=>t.type==='expense').reduce((a,t)=>a+t.amount,0)}}
function catTotals(){const out={};monthTx().filter(t=>t.type==='expense').forEach(t=>out[t.category]=(out[t.category]||0)+t.amount);return out}
function txHtml(t){const c=CATS[t.category]||CATS.기타;return `<article class="transaction" data-tx-id="${t.id}" tabindex="0"><span class="tx-icon" style="background:${c.color}22">${c.icon}</span><div><h3>${esc(t.memo||t.category)}</h3><p>${t.date.replaceAll('-','.')} · ${t.category}</p></div><div><strong class="${t.type}">${t.type==='expense'?'-':'+'}${won(t.amount)}</strong><span class="owner-chip">${t.owner}</span></div></article>`}
function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function render(){const tx=monthTx().sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id),t=totals(),cats=catTotals();document.querySelector('#todayLabel').textContent=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'short'}).format(today);document.querySelector('#monthPicker').textContent=`${viewDate.getFullYear()}년 ${viewDate.getMonth()+1}월`;document.querySelector('#incomeValue').textContent=won(t.income);document.querySelector('#expenseValue').textContent=won(t.expense);document.querySelector('#balanceValue').textContent=won(t.income-t.expense);document.querySelector('#balanceNote').textContent=t.income-t.expense>=0?'차곡차곡 모으는 중이에요':'이번 달 지출을 살펴봐요';const top=Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,4);document.querySelector('#categorySummary').innerHTML=top.length?top.map(([name,val])=>{const pct=t.expense?Math.round(val/t.expense*100):0,c=CATS[name]||CATS.기타;return `<div class="cat-row"><span class="cat-icon" style="background:${c.color}22">${c.icon}</span><div class="cat-info"><p><span>${name}</span><b>${pct}%</b></p><div class="tiny-bar"><i style="width:${pct}%;background:${c.color}"></i></div></div><strong>${won(val)}</strong></div>`}).join(''):'<div class="empty">아직 지출이 없어요. 첫 기록을 남겨보세요!</div>';document.querySelector('#recentList').innerHTML=tx.slice(0,4).map(txHtml).join('')||'<div class="empty">이번 달 내역이 아직 없어요.</div>';renderHistory();renderStats();renderBudget()}
function renderHistory(){const q=document.querySelector('#searchInput').value.trim().toLowerCase();let tx=monthTx().sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);if(filter!=='all')tx=tx.filter(t=>filter==='income'||filter==='expense'?t.type===filter:t.owner===filter);if(q)tx=tx.filter(t=>(t.memo+t.category).toLowerCase().includes(q));document.querySelector('#historyTotal').textContent=`총 ${tx.length}건 · ${viewDate.getMonth()+1}월 기록`;document.querySelector('#historyList').innerHTML=tx.map(txHtml).join('')||'<div class="empty">조건에 맞는 내역이 없어요.</div>'}
function renderStats(){const cats=catTotals(),t=totals();document.querySelector('#statExpense').textContent=won(t.expense);const days=['월','화','수','목','금','토','일'],week=[0,0,0,0,0,0,0];monthTx().filter(x=>x.type==='expense').forEach(x=>{const d=new Date(x.date+'T00:00:00').getDay();week[(d+6)%7]+=x.amount});const max=Math.max(...week,1);document.querySelector('#barChart').innerHTML=week.map((v,i)=>`<div class="bar-col ${i===(today.getDay()+6)%7?'active':''}"><i style="height:${Math.max(4,v/max*100)}%"></i><span>${days[i]}</span></div>`).join('');const entries=Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,5),colors=entries.map(([n])=>(CATS[n]||CATS.기타).color);let pos=0;const grad=entries.map(([,v],i)=>{const start=pos;pos+=t.expense?v/t.expense*100:0;return `${colors[i]} ${start}% ${pos}%`}).join(',');document.querySelector('#donut').style.background=entries.length?`conic-gradient(${grad})`:'#eee8df';document.querySelector('#donutText').textContent=won(t.expense);document.querySelector('#statLegend').innerHTML=entries.map(([n,v],i)=>`<div><i style="background:${colors[i]}"></i><span>${n}</span><b>${t.expense?Math.round(v/t.expense*100):0}%</b></div>`).join('')||'<small>지출을 기록하면 보여드려요.</small>';const top=entries[0];document.querySelector('#spendingComment').textContent=!top?'아직 조용한 달이에요. 첫 지출을 기록해볼까요?':`${top[0]}에 가장 많이 썼어요. 전체 지출의 ${Math.round(top[1]/t.expense*100)}%예요!`}
function renderBudget(){const t=totals(),remain=state.budget-t.expense,pct=state.budget?Math.min(100,t.expense/state.budget*100):0;document.querySelector('#budgetRemain').textContent=won(Math.max(0,remain));document.querySelector('#budgetBar').style.width=pct+'%';document.querySelector('#budgetBar').style.background=pct>90?'#e87368':'';document.querySelector('#budgetCaption').textContent=`${won(state.budget)} 중 ${won(t.expense)} 사용 · ${Math.round(pct)}%`;const cats=catTotals();document.querySelector('#budgetList').innerHTML=EXPENSE_CATS.map(n=>{const c=CATS[n],b=state.catBudgets[n]||0,use=cats[n]||0,p=b?Math.min(100,use/b*100):0;return `<article class="budget-item"><div class="budget-item-head"><div><span class="cat-icon" style="width:30px;height:30px;background:${c.color}22">${c.icon}</span><span>${n}</span></div><button data-budget-cat="${n}">${won(use)} / ${won(b)}</button></div><div class="progress"><i style="width:${p}%;background:${p>90?'#e87368':c.color}"></i></div></article>`}).join('')}
function go(page){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.dataset.page===page));document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));scrollTo({top:0,behavior:'smooth'})}
function openSheet(id=null){editingId=id===null?null:Number(id);const t=state.transactions.find(x=>x.id===editingId);document.querySelector('#entryForm').reset();if(t){entryType=t.type;entryOwner=t.owner;entryCat=t.category;document.querySelector('#amount').value=Number(t.amount).toLocaleString('ko-KR');document.querySelector('#date').value=t.date;document.querySelector('#memo').value=t.memo||'';document.querySelector('#formTitle').textContent='내역 수정';document.querySelector('#deleteEntry').style.display='block'}else{document.querySelector('#date').value=iso(today);document.querySelector('#formTitle').textContent='내역 추가';document.querySelector('#deleteEntry').style.display='none'}document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x.dataset.type===entryType));document.querySelectorAll('[data-owner]').forEach(x=>x.classList.toggle('active',x.dataset.owner===entryOwner));document.querySelector('#entrySheet').classList.add('open');document.querySelector('#sheetBackdrop').classList.add('open');document.body.style.overflow='hidden';renderPicker()}
function closeSheet(){document.querySelector('#entrySheet').classList.remove('open');document.querySelector('#sheetBackdrop').classList.remove('open');document.body.style.overflow=''}
function renderPicker(){const list=entryType==='expense'?EXPENSE_CATS:INCOME_CATS;if(!list.includes(entryCat))entryCat=list[0];document.querySelector('#categoryPicker').innerHTML=list.map(n=>`<button type="button" class="${n===entryCat?'active':''}" data-cat="${n}"><span>${CATS[n].icon}</span>${n}</button>`).join('')}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
document.querySelectorAll('[data-nav],[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.nav||b.dataset.go));document.querySelector('#openForm').onclick=openSheet;document.querySelector('.close-sheet').onclick=closeSheet;document.querySelector('#sheetBackdrop').onclick=closeSheet;document.querySelector('#prevMonth').onclick=()=>{viewDate.setMonth(viewDate.getMonth()-1);render()};document.querySelector('#nextMonth').onclick=()=>{viewDate.setMonth(viewDate.getMonth()+1);render()};document.querySelector('#searchToggle').onclick=()=>document.querySelector('#searchBox').classList.toggle('hidden');document.querySelector('#searchInput').oninput=renderHistory;
document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));renderHistory()});document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{entryType=b.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x===b));renderPicker()});document.querySelectorAll('[data-owner]').forEach(b=>b.onclick=()=>{entryOwner=b.dataset.owner;document.querySelectorAll('[data-owner]').forEach(x=>x.classList.toggle('active',x===b))});document.querySelector('#categoryPicker').onclick=e=>{const b=e.target.closest('[data-cat]');if(b){entryCat=b.dataset.cat;renderPicker()}};
document.querySelector('#amount').oninput=e=>{const n=e.target.value.replace(/\D/g,'');e.target.value=n?Number(n).toLocaleString('ko-KR'):''};document.querySelector('#entryForm').onsubmit=e=>{e.preventDefault();const amount=Number(document.querySelector('#amount').value.replace(/,/g,''));if(!amount)return toast('금액을 입력해 주세요');const record={id:editingId||Date.now(),type:entryType,amount,date:document.querySelector('#date').value,category:entryCat,memo:document.querySelector('#memo').value.trim()||entryCat,owner:entryOwner};if(editingId){const i=state.transactions.findIndex(t=>t.id===editingId);if(i>=0)state.transactions[i]=record}else state.transactions.push(record);save();e.target.reset();closeSheet();render();toast(editingId?'기록을 수정했어요!':'소중한 기록을 저장했어요!');editingId=null};
document.querySelector('#deleteEntry').onclick=()=>{if(!editingId||!confirm('이 기록을 삭제할까요?'))return;state.transactions=state.transactions.filter(t=>t.id!==editingId);save();closeSheet();render();editingId=null;toast('기록을 삭제했어요')};
document.querySelectorAll('#recentList,#historyList').forEach(list=>list.addEventListener('click',e=>{const item=e.target.closest('[data-tx-id]');if(item)openSheet(item.dataset.txId)}));
document.querySelector('#editBudget').onclick=()=>{const v=prompt('이번 달 전체 예산을 입력해 주세요.',state.budget);if(v!==null&&!isNaN(Number(v.replaceAll(',','')))){state.budget=Number(v.replaceAll(',',''));save();renderBudget()}};document.querySelector('#budgetList').onclick=e=>{const b=e.target.closest('[data-budget-cat]');if(!b)return;const n=b.dataset.budgetCat,v=prompt(`${n} 예산을 입력해 주세요.`,state.catBudgets[n]||0);if(v!==null&&!isNaN(Number(v.replaceAll(',','')))){state.catBudgets[n]=Number(v.replaceAll(',',''));save();renderBudget()}};
document.querySelector('#exportButton').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`우리집가계부-${iso(today)}.json`;a.click();URL.revokeObjectURL(a.href);toast('백업 파일을 만들었어요')};document.querySelector('#importInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const data=JSON.parse(r.result);if(!Array.isArray(data.transactions))throw 0;state=data;save();render();toast('백업을 불러왔어요')}catch{toast('올바른 백업 파일이 아니에요')}};r.readAsText(f)};
async function init(){render();try{const remote=await window.firebaseLedger.load();if(remote&&Array.isArray(remote.transactions)){state=remote;localStorage.setItem(STORE,JSON.stringify(state));render()}else await window.firebaseLedger.save(state)}catch{toast('Firebase 연결을 확인해 주세요')}}
init();
